ulder":56,"sleeve":24},{"size":"XL","chest":130,"length":79,"shoulder":58,"sleeve":25},{"size":"XXL","chest":138,"length":81,"shoulder":61,"sleeve":26}]'::jsonb, array['valuable-fish-tee-crisp-white', 'thorny-crown-heavyweight-tee-noir', 'signature-logo-tee-washed-black', 'thorny-crown-heavyweight-tee-blanco']::text[], 0)
